import '@servicenow/sdk/global'
import { StringColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Subflow, Flow, wfa, FlowObject, FlowArray } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// -----------------------------------------------------------------------------
// Subflow with complex inputs
// -----------------------------------------------------------------------------
export const employeeProcessSubflow = Subflow(
    {
        $id: Now.ID['sb_emp_process'],
        name: 'Employee Process',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
        inputs: {
            employee: FlowObject({
                label: 'Employee',
                mandatory: true,
                fields: {
                    name: StringColumn({ label: 'Name', mandatory: true }),
                    email: StringColumn({ label: 'Email', mandatory: true }),
                },
            }),
            tags: FlowArray({
                label: 'Tags',
                mandatory: false,
                elementType: StringColumn({ mandatory: true }),
                childName: 'tag_child0',
            }),
        },
        outputs: {
            processed: BooleanColumn({ label: 'Processed', mandatory: true }),
        },
    },
    (_params) => {}
)

// -----------------------------------------------------------------------------
// Flow that calls the subflow
// -----------------------------------------------------------------------------
Flow(
    {
        $id: Now.ID['flow_complex_subflow'],
        name: 'Flow - Complex Subflow Example',
        description: 'Calls subflow with complex objects',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_emp'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_trg) => {
        // wfa.subflow(
        //     employeeProcessSubflow,
        //     { $id: Now.ID['sb_inst'] },
        //     {
        //         employee: { name: 'Carol', email: 'carol@example.com' },
        //         tags: ['urgent', 'high'],
        //     }
        // )
    }
)
